sql.where:
is_deleted = 0

    AND contract_no = #{req.contractNo}


    AND purchase_order_no = #{req.purchaseOrderNo}


    AND supplier_name LIKE CONCAT('%', #{req.supplierName}, '%')


    AND status = #{req.status}


    AND contract_date >= #{req.startDate}


    AND contract_date <= #{req.endDate}
